import { useState, useCallback } from "react";
import { cn } from "@/lib/utils";

interface SchemaFormProps {
  schema: {
    type?: string;
    properties?: Record<string, SchemaProperty>;
    required?: string[];
    title?: string;
  } | null;
  value: Record<string, unknown>;
  onChange: (value: Record<string, unknown>) => void;
  onSubmit: () => void;
  className?: string;
  disabled?: boolean;
}

interface SchemaProperty {
  type?: string;
  enum?: string[];
  oneOf?: Array<{ const?: string; title?: string }>;
  description?: string;
  minLength?: number;
  maxLength?: number;
  default?: unknown;
}

export function SchemaForm({
  schema,
  value,
  onChange,
  onSubmit,
  className,
  disabled = false,
}: SchemaFormProps) {
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validateField = useCallback((key: string, prop: SchemaProperty, val: unknown): string | null => {
    if (prop.minLength && typeof val === "string" && val.length < prop.minLength) {
      return `Minimum length is ${prop.minLength}`;
    }
    if (schema?.required?.includes(key) && (!val || (typeof val === "string" && val.trim() === ""))) {
      return "This field is required";
    }
    return null;
  }, [schema?.required]);

  const handleFieldChange = (key: string, prop: SchemaProperty, newValue: unknown) => {
    const error = validateField(key, prop, newValue);
    setErrors((prev) => ({ ...prev, [key]: error || "" }));
    onChange({ ...value, [key]: newValue });
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      onSubmit();
    }
  };

  if (!schema || schema.type !== "object" || !schema.properties) {
    return (
      <div className={cn("text-sm text-muted-foreground", className)}>
        No schema available
      </div>
    );
  }

  const properties = schema.properties;

  return (
    <div className={cn("space-y-4", className)}>
      {Object.entries(properties).map(([key, prop]) => (
        <SchemaField
          key={key}
          name={key}
          property={prop}
          value={value[key]}
          error={errors[key]}
          required={schema.required?.includes(key)}
          disabled={disabled}
          onChange={(newValue) => handleFieldChange(key, prop, newValue)}
          onKeyDown={handleKeyDown}
        />
      ))}
    </div>
  );
}

interface SchemaFieldProps {
  name: string;
  property: SchemaProperty;
  value: unknown;
  error?: string;
  required?: boolean;
  disabled?: boolean;
  onChange: (value: unknown) => void;
  onKeyDown: (e: React.KeyboardEvent) => void;
}

function SchemaField({
  name,
  property,
  value,
  error,
  required,
  disabled,
  onChange,
  onKeyDown,
}: SchemaFieldProps) {
  const label = property.description || name;

