          )}
        >
          {!required && <option value="">-- Select {label} --</option>}
          {property.oneOf.map((opt) => (
            <option key={opt.const} value={opt.const}>
              {opt.title || opt.const}
            </option>
          ))}
        </select>
        {error && <span className="text-xs text-danger">{error}</span>}
      </div>
    );
  }

