                "model": request.model,
                "non_sandboxed": request.non_sandboxed
            }))
        }
        Err(e) => Json(json!({
            "success": false,
            "model": request.model,
            "note": e.to_string()
        })),
    }
}

#[derive(Debug, Deserialize)]
