/// Gemini API base URL
const GEMINI_API_BASE: &str = "https://generativelanguage.googleapis.com/v1beta";

/// Available models through Antigravity/Gemini
const ANTIGRAVITY_MODELS: &[(&str, &str, &str)] = &[
    (
        "gemini-2.0-flash",
        "Gemini 2.0 Flash",
        "Fast, efficient, and cost-effective",
    ),
